"use client";
/**
 * Form fields: Field (label/hint/error wrapper), Input, PasswordInput, Select,
 * NumberInput (+ parseDecimal helper). Labels are always rendered (use
 * `hideLabel` to make one screen-reader only).
 */
import { useId, useState, type InputHTMLAttributes, type ReactNode, type SelectHTMLAttributes } from "react";
import { cx } from "./cx";
import { Icon } from "./icons";
import { controlStyles, parseDecimal } from "./number";

export interface FieldProps {
  label: ReactNode;
  /** id of the control; generated by the control components. */
  htmlFor: string;
  hint?: ReactNode;
  error?: ReactNode;
  hideLabel?: boolean;
  /** Text shown right of the label (e.g. "Opcional"). */
  aside?: ReactNode;
  className?: string;
  children: ReactNode;
}

export function Field({ label, htmlFor, hint, error, hideLabel, aside, className, children }: FieldProps) {
  return (
    <div className={cx("flex flex-col gap-1.5", className)}>
      <div className={cx("flex items-baseline justify-between gap-2", hideLabel && "sr-only")}>
        <label htmlFor={htmlFor} className="text-sm font-semibold text-fg">
          {label}
        </label>
        {aside ? <span className="text-xs text-fg-subtle">{aside}</span> : null}
      </div>
      {children}
      {error ? (
        <p id={`${htmlFor}-error`} className="flex items-center gap-1.5 text-sm font-medium text-danger">
          <Icon.Alert className="size-4 shrink-0" />
          {error}
        </p>
      ) : hint ? (
        <p id={`${htmlFor}-hint`} className="text-sm text-fg-subtle">
          {hint}
        </p>
      ) : null}
    </div>
  );
}

function describedBy(id: string, hint: unknown, error: unknown) {
  return error ? `${id}-error` : hint ? `${id}-hint` : undefined;
}

export interface InputProps extends Omit<InputHTMLAttributes<HTMLInputElement>, "size"> {
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  hideLabel?: boolean;
  aside?: ReactNode;
  /** Wrapper className (the <input> gets `inputClassName`). */
  className?: string;
  inputClassName?: string;
  /** Element rendered inside the input on the right (e.g. a toggle button). */
  trailing?: ReactNode;
}

export function Input({
  label,
  hint,
  error,
  hideLabel,
  aside,
  className,
  inputClassName,
  trailing,
  id,
  ...rest
}: InputProps) {
  const autoId = useId();
  const inputId = id ?? autoId;
  return (
    <Field label={label} htmlFor={inputId} hint={hint} error={error} hideLabel={hideLabel} aside={aside} className={className}>
      <div className="relative">
        <input
          id={inputId}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy(inputId, hint, error)}
          className={cx(controlStyles, error ? "border-danger" : "border-line", trailing ? "pr-12" : "", inputClassName)}
          {...rest}
        />
        {trailing ? <div className="absolute inset-y-0 right-0 flex items-center pr-0.5">{trailing}</div> : null}
      </div>
    </Field>
  );
}

/** Password input with show/hide toggle. */
export function PasswordInput(props: Omit<InputProps, "type" | "trailing">) {
  const [visible, setVisible] = useState(false);
  return (
    <Input
      {...props}
      type={visible ? "text" : "password"}
      autoCapitalize="none"
      autoCorrect="off"
      spellCheck={false}
      trailing={
        <button
          type="button"
          onClick={() => setVisible((v) => !v)}
          className="inline-flex size-11 items-center justify-center rounded-md text-fg-muted hover:text-fg"
          aria-label={visible ? "Ocultar contraseña" : "Mostrar contraseña"}
          aria-pressed={visible}
        >
          {visible ? <Icon.EyeOff /> : <Icon.Eye />}
        </button>
      }
    />
  );
}

export interface SelectProps extends SelectHTMLAttributes<HTMLSelectElement> {
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  hideLabel?: boolean;
  options: ReadonlyArray<{ value: string; label: string; disabled?: boolean }>;
  /** Wrapper className. */
  className?: string;
}

/** Native <select> (best mobile UX: OS picker). */
export function Select({ label, hint, error, hideLabel, options, className, id, ...rest }: SelectProps) {
  const autoId = useId();
  const selectId = id ?? autoId;
  return (
    <Field label={label} htmlFor={selectId} hint={hint} error={error} hideLabel={hideLabel} className={className}>
      <div className="relative">
        <select
          id={selectId}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy(selectId, hint, error)}
          className={cx(controlStyles, "appearance-none pr-10", error ? "border-danger" : "border-line")}
          {...rest}
        >
          {options.map((o) => (
            <option key={o.value} value={o.value} disabled={o.disabled}>
              {o.label}
            </option>
          ))}
        </select>
        <Icon.ChevronDown className="pointer-events-none absolute top-1/2 right-3 size-5 -translate-y-1/2 text-fg-muted" />
      </div>
    </Field>
  );
}

export interface NumberInputProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, "value" | "onChange" | "size" | "type" | "inputMode"> {
  label: ReactNode;
  hideLabel?: boolean;
  hint?: ReactNode;
  error?: ReactNode;
  /** Controlled text value (keep it a string so "35." can be typed). */
  value: string;
  onValueChange: (value: string) => void;
  /** "decimal" for weights (allows . and ,), "numeric" for reps/RPE integers. Default "decimal". */
  mode?: "decimal" | "numeric";
  /** Unit/suffix shown inside the field ("lb", "reps"). */
  suffix?: ReactNode;
  /** Show −/+ steppers that add/subtract `step` (default 1; e.g. 5 for lb). */
  steppers?: boolean;
  step?: number;
  min?: number;
  max?: number;
  /** "md" = 48px, "lg" = 56px with big display digits (set rows). */
  size?: "md" | "lg";
  className?: string;
}

function trimNum(n: number) {
  return `${Number(n.toFixed(2))}`;
}

/**
 * Big numeric field for gym logging. Uses type="text" + inputMode so mobile
 * shows the numeric keypad without the browser mangling partial input.
 */
export function NumberInput({
  label,
  hideLabel,
  hint,
  error,
  value,
  onValueChange,
  mode = "decimal",
  suffix,
  steppers = false,
  step = 1,
  min = 0,
  max,
  size = "md",
  className,
  id,
  disabled,
  ...rest
}: NumberInputProps) {
  const autoId = useId();
  const inputId = id ?? autoId;
  const filter = mode === "decimal" ? /[^\d.,]/g : /\D/g;

  const bump = (dir: 1 | -1) => {
    const current = parseDecimal(value) ?? parseDecimal(String(rest.placeholder ?? "")) ?? 0;
    let next = current + dir * step;
    if (next < min) next = min;
    if (max !== undefined && next > max) next = max;
    onValueChange(trimNum(next));
  };

  const input = (
    <div className="relative flex-1">
      <input
        id={inputId}
        type="text"
        inputMode={mode}
        pattern={mode === "decimal" ? "[0-9]*[.,]?[0-9]*" : "[0-9]*"}
        autoComplete="off"
        enterKeyHint="next"
        value={value}
        disabled={disabled}
        onChange={(e) => onValueChange(e.target.value.replace(filter, ""))}
        onFocus={(e) => e.currentTarget.select()}
        aria-invalid={error ? true : undefined}
        aria-describedby={describedBy(inputId, hint, error)}
        className={cx(
          controlStyles,
          "nums text-center",
          size === "lg" ? "min-h-14 font-display text-[1.75rem] font-bold" : "text-lg font-semibold",
          suffix ? "pr-10" : "",
          error ? "border-danger" : "border-line",
        )}
        {...rest}
      />
      {suffix ? (
        <span className="pointer-events-none absolute top-1/2 right-3 -translate-y-1/2 text-xs font-semibold text-fg-subtle uppercase">
          {suffix}
        </span>
      ) : null}
    </div>
  );

  return (
    <Field label={label} htmlFor={inputId} hint={hint} error={error} hideLabel={hideLabel} className={className}>
      {steppers ? (
        <div className="flex items-stretch gap-1.5">
          <button
            type="button"
            onClick={() => bump(-1)}
            disabled={disabled}
            aria-label={`Restar ${step}`}
            className="inline-flex w-12 shrink-0 items-center justify-center rounded-lg border border-line bg-surface-2 text-fg active:scale-95 disabled:opacity-40"
          >
            <Icon.Minus />
          </button>
          {input}
          <button
            type="button"
            onClick={() => bump(1)}
            disabled={disabled}
            aria-label={`Sumar ${step}`}
            className="inline-flex w-12 shrink-0 items-center justify-center rounded-lg border border-line bg-surface-2 text-fg active:scale-95 disabled:opacity-40"
          >
            <Icon.Plus />
          </button>
        </div>
      ) : (
        input
      )}
    </Field>
  );
}
